package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaSoDraft7 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_jar_su" to DuaText("Deris Xun Oo Laga Qaxo", "Allahayow waxaan kaa magan galayaa daris xun oo ku sugan meesha uu daganyahay, jaarku safar buu u socdaa.", "Si looga ilaaliyo deris xun.", "Nabiga ﷺ wuxuu amray in laga magan galo tan."),
        "dua_ishfi_abdak" to DuaText("Soo Kabashada Qofka Xanuunsan", "Allahayow anoo addoonkaaga ah dawee si uu cadawgaada ula kulmo ama uu salaada kuugu socdo.", "Qofka buka marka uu booqanayo.", "Nebigu ﷺ baa baray isagoo tan buka leh."),
        "dua_la_mania" to DuaText("Midna ma celin karo waxaad bixiso", "Ma jiro cid xaq u leh in la caabudo Allaah mooyee, Isaga oo keliya, oo aan la wadaagin. Xukunka isagaa iska leh mahadna isagaa iska leh, wax walbana wuu karaa. Allahayow waxaad siiso cid celin karta ma jirto, waxaad celisana ma jirto, hantida maalqabeenaduna wax kaa tari mayso.", "Ka dib salaamaha salaadda faralka ah.", "Nabigu ﷺ waxa uu yidhi salaad kasta oo waajib ah ka dib."),
        "dua_slaughtering" to DuaText("Marka Xoolaha la gowraco", "Magaca Eebe yaan ku billaabaynaa, Allaahna waa kan ugu weyn.", "Marka la gowraco ama la gowrayo neefka.", "Nebigu ﷺ wuxuu yidhi Bismillah iyo takbiir markii la huray."),
        "dua_undressing" to DuaText("Marka Dharka laga qaadayo", "Magaca Allaah.", "Markaad dharka iska siibaynayso (guusl ama beddelaad).", "Waxa ay noqotaa shaashad u dhaxaysa indhaha jinniga iyo xubinta qofka."),
        "dua_ilbas_jadidan" to DuaText("Inaad Aragto Qof Lebisan Dhar Cusub", "Xiro cusub, noolow ammaanta iyo geeri shahiid.", "Markaan arkay walaal muslim ah oo dhar cusub xidhan.", "Nabigu ﷺ wuxuu ducadan sameeyay markuu arkay Cumar (RA) oo dhar cusub xidhan."),
        "dua_hajj_la_riya" to DuaText("Xajka Xorta ah ee Istuska", "Allow (ka yeel) Xaj aan is muujin iyo magac doon midna.", "Daacadnimo marka la niyeynayo xajka.", "Nabigu ﷺ waxa uu ducadan sameeyay xiligii xajka."),
        "dua_q_muslimayni_laka" to DuaText("Ducadii Ibraahiim & Ismaaciil (AS) — Nooga dhig kuwo is-dul-saaran", "Eebow naga yeel mid adiga iyo faracyadanada u hogaansama. Na tus cibaadadayada oo ka toobad keen. Ee adaa aqbal toobada Naxariista.", "Ducada is-hoosaysiinta nafteeda iyo ta faraceeda.", "Ducada la sameeyay markii la dhisayay Kacbada."),
        "dua_q_iftah_baynana" to DuaText("Ducadii Shucayb (AS) - Garsoore Dhexdeenna", "Eebow nagu kala xukun dhexdeenna iyo qoomkannada si xaq ah, adigaa u khayrroon xaakim.", "Si loo kala xukumo runta iyo beenta.", "Ducadii Shucayb (AS) markay qoomkiisii ​​diideen."),
        "dua_q_la_akuna_zahiran" to DuaText("Dua of Musa (AS) - Waligaa caawiye dambiilayaasha", "Eebow Nicmadaad igu Nicmaysay Darteed uma noqonayo Gargaar Dambiilayaasha.", "Ku shukrinta nimcooyinka Alle iyo ballan ah inaan loo gargaarin daalimiinta.", "Ballanqaadkii Muuse (AS) ka dib markii uu toobad keenay."),
        "dua_q_nuh_unsurni" to DuaText("Ducadii Nuux (AS) - I caawi, way i dafireen", "Rabbiyow, i caawi, waayo, way i diideen.", "Dadku markay ku beeniyaan oo xaqa diidaan.", "Ducada Nuux (AS), oo laga jawaabay."),
        "dua_q_ihkum_bil_haqq" to DuaText("Eebow xaqa ku kala xukun", "Eebow xaqa ku kala xukun. Eebahanno waa Naxariista, waxaana gargaarkiisa la warsan waxaad ku tilmaami.", "Beenta iyo eedaymaha beenta ah ee la isku haysto.", "Duco la baray nabiga ﷺ."),
        "dua_ghalabatid_dayn" to DuaText("Ka Badbaadinta Dulmiga iyo Cadawga", "Allahayow waxaan kaa magan galay inaan dayn kugu daaho, oo aan cadawga ka adkaado, cadawgana aan ku faanin.", "Ka ilaalinta culayska deynta iyo xukunka cadowgu.", "Nebigu ﷺ wuu ka magan geli jiray waxyaalahaas."),
        "dua_faqr_qillah_dhillah" to DuaText("Faqriga iyo dullinimada laga magan galo", "Allahayow waxaan kaa magan galayaa faqri, gabaabsi iyo dullinimo iyo inaad cid kale dulmido ama la dulmiyo.", "Si aad uga nabad gasho dhibka, baahida iyo dulliga.", "Gabaad uu nabigu baray ﷺ."),
        "dua_five_things_new_muslim" to DuaText("Cafi, Naxariista, Hanuuniye, Caafi, Bixi", "Allahayow ii dambi dhaaf, ii naxariiso, i hanuuni, wanaagna i sii oo i arsaaqi.", "Nebigu ﷺ baray ducadan, oo ay weheliso ducada, Muslimiinta cusub.", "Nebigu ﷺ wuxuu yidhi: erayadani waxay idiin soo ururiyaan adduun iyo aakhiraba."),
        "dua_ruku_laka_raka_tu" to DuaText("In Ruku- Adiga Adaan U Sujuuday", "Allow adaan kuu sujuuday, adigaan ku rumeeyay adigana waan kuu hogaansamay. Maqalkayga, araggayga, maskaxdayda, lafahayga iyo seedahaygaba hortaaday ku hoosayseen.", "In rukuucda (gaar ahaan salaadaha iskaa wax u qabso ah).", "Nebigu ﷺ wuxuu ku akhriyey rukuuc."),
        "dua_sujood_laka_sajadtu" to DuaText("Sujuud - Adiga ayaan kuu Sujuuday", "Allow adigaan kuu sujuuday, adigaan ku rumeeyay adigana waan kuu sakhiray. Wajigayga wuxuu u sujuuday Eebaha abuuray ee qaabeeyey una soo bixiyey maqalkiisa iyo aragiisa. Waxaa mahad leh Allaha ugu khayrka badan abuurista.", "Sujuud (gaar ahaan salaadaha iskaa wax u qabso ah).", "Nabigu ﷺ ayaa sujuud ku akhriyay."),
        "dua_ruku_sujood_subhanaka" to DuaText("Subxaanahu Wa Tacaalaa, Rabbiyow - I cafi", "Subxaana watacaalaa, Rabbiyow, adigaa mahad leh. Allahayow i cafi.", "In rukuuc iyo sujuud.", "Caa’isha (RA): Nabigu ﷺ waxa uu in badan ku yidhi rukuuc iyo sujuud."),
        "dua_q_musa_li_akhi" to DuaText("Ducadii Muuse (AS) - I cafi aniga iyo walaalkay", "Eebow u dambi dhaaf aniga iyo walaalkay oo na gali naxariistaada, adigaa Naxariis badane ah.", "Cafiska naftiisa iyo walaalkii ama gacaliyaha.", "Ducadii Muuse (AS) ee Haaruun (AS)."),
        "dua_q_ufawwidu_amri" to DuaText("Arrinkayga Alle ayaan u wakiishay", "Arrinkaygana Alle ayaan u wakiishay. Eebana addoomadiisa waa arka.", "Marka dadku idinka soo horjeestaan ​​arrinka waa in Allaah loo daayo.", "Hadalkii Mu’minka oo ka yimid Qoomkii Fircoon; Eebbana wuu ka dhawray dhagartooda xun."),
        "dua_q_hawariyyun" to DuaText("Ducada xerta - Noo qor Markhaatiyaasha", "Eebow waan rumaynay waxaad soo dejisay, waxaana raacnay Rasuulka ee nooga qor maragga.", "Ku samirka iimaanka iyo raacidda Rasuulka.", "Ducadii xertii Isa (AS)."),
        "dua_q_la_tukhzini" to DuaText("Dua of Ibrahim (AS) — Ha I ceebayn", "Hana i ceebayn maalinta la soo bixin.", "In laga nabad galo dulliga maalinta qiyaame.", "Ducadii Ibraahim (AS) Aakhiro."),
        "dua_iftar_laka_sumtu" to DuaText("Afur - Adiga Ayaan U Soomay", "Allow adiga waan ku soomay arsaaqdaadana waan ku afuray.", "Marka la afurayo (ducada afurka ee caanka ah).", "Nabigu ﷺ waxa uu yidhi afurka. Waa mursal mursal oo ay sii xoojiyeen riwaayado kale; akhrinta afurka waa dhaqankii Xanafiyada iyo inta badan."),
        "dua_iftar_ibn_umar" to DuaText("Afur - Naxariistaada wayn, I cafi", "Allahayow waxaan ku waydiisanayaa naxariistaada koobaysa wax walba inuu ii dambi dhaafo.", "Markii la afuray - Cabdullaahi ibn Camr (RA) ayaa ducadan sameeyey; ducada qofka sooman afurka lama diido.", "Xadiiska: ducada qofka sooman wakhtiga afurka lama diido."),
        "dua_inni_saim" to DuaText("Marka laga xanaajiyo Inta Sooman", "waan soomanahay, waan soomanahay.", "Marka qof ku aflagaadeeyo ama kugu murmo isagoo sooman.", "Nebigu ﷺ wuxuu yidhi: Soonku waa gaashaan, sidaa darteed qofka sooman waa inaanu ku hadlin xumaan ama jaahilnimo - haddii qof muran galo, laba jeer dheh."),
        "dua_eid_takbeer" to DuaText("Takbiirta Waddada Ciidda", "Allaah baa weyn, Allaah baa weyn, Allaah mooyee ilaah kale ma jiro, Allaah baa weyn, Allaah ayaa weyn, mahad oo dhan Allaah ayaa iska leh.", "Laga soo bilaabo habeenka dayaxa ilaa salaada ciidul fidriga gaar ahaan wadada dhulka ciida.", "Amarka Quraanka: 'Si aad u dhammaystirtaan tirinta oo aad u sheegtaan weynaanta Eebe' (al-Baqarah 2:185). Ibnu Mascuud (RA) ayaa yidhi takbiirtan."),
        "dua_ahsin_aqibatana" to DuaText("Aakhirkayaga Ka dhig mid Wanaagsan dhammaan Arrimaha", "Allow aakhiradeena ka dhig mid u wanagsan amuuraha dhan, naga ilaali ceeb adduun iyo cadaabka aakhiro.", "Si loo helo natiijo wanaagsan arrin kasta.", "Qofkii ducadan sameeya oo dhinta intaan la maxkamadayn wuu dhimanayaa (oo ka badbaadsan maxkamad)."),
        "dua_fadlika_wa_rahmatik" to DuaText("Waxaan ku waydiisanayaa fadligaaga iyo naxariistaada", "Allahayow waxaan ku waydiisanayaa fadligaada iyo naxariistaada, waayo, ma jiro iyaga oo aan adiga ahayn.", "Marka la waydiisto rizqi iyo naxariis.", "Martidu waxay u yimaadeen Nabiga ﷺ markii cunto la'aan; ducadaan ayuu sameeyay, ka dibna hadiyad ayaa timid."),
        "dua_allahu_akbar_kabira_2696" to DuaText("Erayada Lagu Baray Reer Baadiyaha", "Ma jiro cid xaq u leh in la caabudo Allaah mooyee, Isaga oo keliya, oo aan la wadaagin. Eebbana waa kan ugu weyn, aad u weyn; Mahad Eebaa iska leh; Mahad Eebaa iska leh Eebaha Caalamka; xoog iyo xoogna ma jiro Eebe agtiisa ah ee adkaada ee falka san.", "Weedho dhammaystiran oo dhikr iyo duco ah - baray reer baadiyaha.", "Intaa ka dib waxaa la baray inuu yiraahdo 'Allaahummaghfir li warhamni wahdini warzuqni'."),
        "dua_ma_qaddamtu_akhkhartu" to DuaText("Wixii aan soo diray ka hor iyo ka dibba iga cafi", "Allahayow ii dhaaf dambigii aan galay ka hor iyo ka dib, wixii aan si qarsoodi ah u falay iyo wixii aan si cad u falay, xad gudubkayga iyo waxa aad iga aqoon badan tahay. Adiga ayaa hor keenaya oo dib u dhigaya; Adiga mooyee ilaah kale ma jiro.", "Tashahhud iyo salawaat ka dib, salaam ka hor.", "Nebigu ﷺ wuxuu akhriyey tan markay dhammaatay salaadda, inta u dhaxaysa tashahud iyo salaam."),
        "dua_jiddi_wa_hazli" to DuaText("I cafi Dareenkayga iyo Jeestkayga", "Allahayow iga cafi dembiyada aan galay si dhab ah oo jeesjees ah, qalad iyo ula kac ah - waxaas oo dhamina aniga ayay igu jiraan.", "Cafiska nooc kasta oo dembi ah, la yaqaan iyo kuwa aan la garanayn.", "Taariikhdii Nabiga ﷺ."),
        "dua_rising_ruku_mil" to DuaText("Ruku dabadii - Amaan Samooyinka Buuxinaya", "Eebow mahad adigaa iska leh, oo samooyinka ka buuxa, dhulkana ka buuxin, oo waxaad doontid ka dib buuxin.", "Ka dib markii ay ka soo kaceen ruku, oo ay la socdaan 'Rabbana lakal-xamd'.", "Nebigu ﷺ wuxuu yidhi sidan markuu rukuuc ka soo kacay."),
        "dua_istiftah_kabira" to DuaText("Eebaa Wayn, Mahad Badani", "Eebbana waa kan ugu weyn, aad u weyn; Mahad Eebaa iska leh; Subxaana Allaah Subxaana Watacaalaa.", "Marka la bilaabayo salaadda (hal nooc oo ammaanta furitaanka ah).", "Nabigu ﷺ wuxuu yidhi: albaabada jannada waa laga furay."),
        "dua_q_ashku_bathhi" to DuaText("Ducadii Yacquub (AS) - Allaah kaliya ayaan ka dacwoodaa", "Cidhiidhigayga iyo murugadayda waxaan ka cabanayaa Allaah oo keliya.", "In murugo qoto dheer iyo kala fogaansho.", "Yacquub (AS) waxa uu sidaa yidhi markii uu ka soocay Yuusuf (AS)."),
        "dua_q_khayrun_hafiza" to DuaText("Allaah ayaa ugu wanagsan", "Eebbana waa gargaaraha ugu wanaagsan, waana naxariista guud ee naxariista.", "Markaad u dirayso caruur ama kuwa aad jeceshahay safarka.", "Yacquub (AS) wuxuu sidaa yiri isagoo wiilkiisa u wakiishay."),
        "dua_q_aqraba_rashada" to DuaText("Eebbahay ha igu hanuuniyo mid midigta u dhaw", "Wuxuu u dhawyahay inuu Eebahay igu hanuuniyo waxa ka dhaw kan xaqa ah.", "Marka aad raadinayso hab ka wanaagsan arrinka qaarkood.", "Nabiga ﷺ waxa loo sheegay in uu sidaas yidhaahdo markuu illowdo."),
        "dua_q_sawa_as_sabil" to DuaText("Dua of Musa (AS) - Igu Hanuuniyo Jidka Toosan", "Wuxuu u dhawyahay inuu Eebahay igu hanuuniyo jidka toosan.", "Markaad u baxayso safar cusub ama waddo aan la aqoon.", "Muuse (AS) ayaa sidaa yidhi markuu Madyan u jeestay."),
        "dua_q_not_among_wrongdoers" to DuaText("Ha igu dhex gelin Daalimiinta", "Eebow ha iga dhigin qoom daalimiinta ah.", "Ducada Alle ka baryo inuu ka fogeeyo daalimiinta.", "Ducada Alle ka baryo inuu ka fogeeyo daalimiinta."),
        "dua_q_do_not_make_us_trial" to DuaText("Ha naga dhigin Tijaabo", "Eebow ha nooga dhigin fitno gaalada, ee noo dambi dhaaf Eebow. Ee adaa adkaade falsane.", "Ducadii Ibraahim (AS) iyo asxaabtiisa.", "Ducadii Ibraahim (AS) iyo asxaabtiisa."),
        "dua_morning_witness" to DuaText("Subaxdii Tawxiidka", "Allaahow, waxaan galay subaxii anigoo markhaati ka dhigaya Adiga, kuwa Carshigaaga xambaara, malaa’igtaada iyo dhammaan makhluuqaadkaaga, in Adigu tahay Allaah, ilaah xaq lagu caabudo ma jiro Adiga mooyee, Adiga oo keliya, oo aan la wadaagin, iyo in Muxammad ﷺ yahay addoonkaaga iyo Rasuulkaaga.", "Qisadu waxay sheegtay in afar jeer subaxdii la yidhi.", "Qisadu waxay sheegtay in afar jeer subaxdii la yidhi."),
    )
}
